<?php require '../config/auth.php';login_required('student');$page_title='My Profile';$uid=$_SESSION['user_id'];$q=$pdo->prepare('SELECT s.*,u.email FROM students s JOIN users u ON u.id=s.user_id WHERE s.user_id=?');$q->execute([$uid]);$s=$q->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$photo=upload('profile_photo','profiles',['jpg','jpeg','png','webp']);$resume=upload('resume','resumes',['pdf','doc','docx']);$sql='UPDATE students SET full_name=?,mobile=?,dob=?,gender=?,address=?,college=?,course=?,department=?,year=?,semester=?,roll_number=?,prn=?,cgpa=?,skills=?,certifications=?';$p=[$_POST['full_name'],$_POST['mobile'],$_POST['dob']?:null,$_POST['gender'],$_POST['address'],$_POST['college'],$_POST['course'],$_POST['department'],$_POST['year'],$_POST['semester'],$_POST['roll_number'],$_POST['prn'],$_POST['cgpa']?:null,$_POST['skills'],$_POST['certifications']];if($photo){$sql.=',profile_photo=?';$p[]=$photo;}if($resume){$sql.=',resume=?';$p[]=$resume;}$sql.=' WHERE user_id=?';$p[]=$uid;$pdo->prepare($sql)->execute($p);$pdo->prepare('UPDATE users SET name=?,email=? WHERE id=?')->execute([$_POST['full_name'],$_POST['email'],$uid]);flash('Profile updated successfully.');go('profile.php');}require '../config/header.php';flashes();?><div class="head"><div><h1>My Profile</h1><p>Update personal, academic and professional information.</p></div></div><form method="post" enctype="multipart/form-data" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="card"><div class="row"><div class="fg"><label>Full Name</label><input class="control" name="full_name" value="<?=e($s['full_name'])?>" required></div><div class="fg"><label>Email</label><input class="control" name="email" type="email" value="<?=e($s['email'])?>" required></div></div><div class="row"><div class="fg"><label>Mobile</label><input class="control" name="mobile" value="<?=e($s['mobile'])?>"></div><div class="fg"><label>Date of Birth</label><input class="control" name="dob" type="date" value="<?=e($s['dob'])?>"></div></div><div class="row"><div class="fg"><label>Gender</label><select class="control" name="gender"><option>Male</option><option>Female</option><option>Other</option></select></div><div class="fg"><label>College</label><input class="control" name="college" value="<?=e($s['college'])?>"></div></div><div class="row"><div class="fg"><label>Course</label><input class="control" name="course" value="<?=e($s['course'])?>"></div><div class="fg"><label>Department</label><input class="control" name="department" value="<?=e($s['department'])?>"></div></div><div class="row"><div class="fg"><label>Year</label><input class="control" name="year" value="<?=e($s['year'])?>"></div><div class="fg"><label>Semester</label><input class="control" name="semester" value="<?=e($s['semester'])?>"></div></div><div class="row"><div class="fg"><label>Roll Number</label><input class="control" name="roll_number" value="<?=e($s['roll_number'])?>"></div><div class="fg"><label>PRN</label><input class="control" name="prn" value="<?=e($s['prn'])?>"></div></div><div class="row"><div class="fg"><label>CGPA</label><input class="control" name="cgpa" type="number" step=".01" min="0" max="10" value="<?=e($s['cgpa'])?>"></div><div class="fg"><label>Profile Photo</label><input class="control" name="profile_photo" type="file" accept=".jpg,.jpeg,.png,.webp"></div></div><div class="fg"><label>Address</label><textarea class="control" name="address"><?=e($s['address'])?></textarea></div><div class="fg"><label>Skills</label><textarea class="control" name="skills"><?=e($s['skills'])?></textarea></div><div class="fg"><label>Certifications</label><textarea class="control" name="certifications"><?=e($s['certifications'])?></textarea></div><div class="fg"><label>Resume</label><input class="control" name="resume" type="file" accept=".pdf,.doc,.docx"></div><button class="btn primary">Save Changes</button><?php if($s['resume']):?><a class="btn outline" target="_blank" href="../<?=e($s['resume'])?>">View Resume</a><?php endif;?></div></form><?php require '../config/footer.php';?>
